    fn an_empty_line_keeps_the_marked_ones_and_one_pick_needs_exactly_one() {
        let listed = names(&["a", "b", "c"]);
        assert_eq!(answer("  ", &listed, &[false, true, true], false), Ok(vec![1, 2]));
